package com.clavis.reader;
import android.animation.ValueAnimator;import android.view.*;import android.view.animation.DecelerateInterpolator;import android.widget.*;import androidx.recyclerview.widget.RecyclerView;import java.util.*;
/** Reclaims header space while reading lists; scrolling toward earlier content restores it. */
final class ScrollChrome {
 static final WeakHashMap<View,Controller> active=new WeakHashMap<>();
 static View scroll(View view){if(view instanceof ScrollView||view instanceof RecyclerView)return view;if(view instanceof ViewGroup)for(int n=0;n<((ViewGroup)view).getChildCount();n++){View found=scroll(((ViewGroup)view).getChildAt(n));if(found!=null)return found;}return null;}
 static void install(MainActivity a){if(a.getClass()!=MainActivity.class)return;String screen=a.screen;if(!(screen.equals("Home")||screen.equals("Audio")||screen.equals("EPUB")||screen.equals("PDF")||screen.equals("News")||screen.equals("Journals")||screen.equals("Podcasts")||screen.endsWith(" feed")||screen.equals("Podcasts browse")))return;View content=scroll(a.root);if(content==null||active.containsKey(content))return;Controller controller=new Controller(a,content);active.put(content,controller);controller.bind();}
 static Controller story(MainActivity a,boolean reading){View content=scroll(a.root);Controller controller=active.get(content);if(controller==null)return null;controller.suspended=true;if(controller.animator!=null)controller.animator.cancel();for(Header header:controller.headers){int measured=header.view.getHeight();if(measured>0)header.height=measured;else if(header.originalHeight>0)header.height=header.originalHeight;}controller.movement=0;if(!reading){controller.hidden=false;controller.fraction=0;}return controller;}
 static void touch(MainActivity a,MotionEvent event){if(a.getClass()!=MainActivity.class||a.root==null||a.bar==null)return;Controller controller=active.get(scroll(a.root));if(controller==null)return;if(event.getActionMasked()==MotionEvent.ACTION_DOWN){controller.touchX=event.getX();controller.touchY=event.getY();controller.lastTouchY=event.getY();controller.userDirection=0;controller.top.returning=false;}else if(event.getActionMasked()==MotionEvent.ACTION_MOVE){float dx=event.getX()-controller.touchX,dy=event.getY()-controller.touchY,change=event.getY()-controller.lastTouchY;controller.lastTouchY=event.getY();if(Math.abs(dy)>Math.abs(dx)*1.2f&&Math.abs(dy)>ViewConfiguration.get(a).getScaledTouchSlop()&&change!=0){controller.userDirection=change>0?-1:1;controller.top.scrolled(controller.userDirection);}if(dy>ViewConfiguration.get(a).getScaledTouchSlop()&&dy>Math.abs(dx)*1.2f&&(a.bar.getVisibility()==View.GONE||a.bar.getHeight()<a.dp(32)))reveal(a);}}
 static void reveal(MainActivity a){FeedPosts.cancelCenter(a);Controller controller=active.get(scroll(a.root));if(controller!=null){controller.suspended=false;if(a.bar.getVisibility()==View.GONE){controller.hidden=true;controller.fraction=1;}controller.setHidden(false);if(controller.userDirection<0)controller.top.scrolled(-1);}else{a.bar.setVisibility(View.VISIBLE);a.bar.getLayoutParams().height=a.dp(64);a.bar.setAlpha(1);a.bar.requestLayout();}}
 static final class Header {final View view;final int originalHeight;int height;Header(View v){view=v;originalHeight=v.getLayoutParams().height;height=v.getHeight();}}
 static final class Controller implements View.OnAttachStateChangeListener {
  final MainActivity a;final View content;final ScrollTopPill top;final ArrayList<Header> headers=new ArrayList<>();ValueAnimator animator;RecyclerView.OnScrollListener listener;float fraction,touchX,touchY,lastTouchY;int movement,userDirection;boolean hidden,closed,suspended;
  Controller(MainActivity a,View content){this.a=a;this.content=content;View child=content;while(child.getParent() instanceof ViewGroup){ViewGroup parent=(ViewGroup)child.getParent();if(parent instanceof LinearLayout&&((LinearLayout)parent).getOrientation()==LinearLayout.VERTICAL){for(int n=0;n<parent.indexOfChild(child);n++){View v=parent.getChildAt(n);if(v.getVisibility()!=View.GONE)headers.add(new Header(v));}}if(parent==a.root)break;child=parent;}top=new ScrollTopPill(a,content,()->{int height=0;for(Header header:headers)if(header.view.getVisibility()!=View.GONE)height+=header.view.getHeight();return height;});}
  void bind(){content.addOnAttachStateChangeListener(this);if(content instanceof RecyclerView){listener=new RecyclerView.OnScrollListener(){@Override public void onScrolled(RecyclerView v,int dx,int dy){moved(dy);}};((RecyclerView)content).addOnScrollListener(listener);}else content.setOnScrollChangeListener((v,x,y,oldX,oldY)->moved(y-oldY));}
  void moved(int dy){if(closed)return;if(content instanceof RecyclerView&&((RecyclerView)content).getScrollState()==RecyclerView.SCROLL_STATE_IDLE){top.scrolled(0);return;}if(userDirection!=0&&Integer.signum(dy)!=userDirection)return;top.scrolled(dy);if(closed||suspended||dy==0||animator!=null&&animator.isRunning())return;if(!content.canScrollVertically(-1)){movement=0;setHidden(false);return;}if(Integer.signum(dy)!=Integer.signum(movement))movement=0;movement+=dy;if(Math.abs(movement)>=a.dp(8)){setHidden(movement>0);movement=0;}}
  void setHidden(boolean value){if(closed||hidden==value)return;hidden=value;for(Header h:headers){if(!value)h.view.setVisibility(View.VISIBLE);if(fraction==0)h.height=h.view.getHeight();if(h.height<=0&&h.originalHeight>0)h.height=h.originalHeight;}if(animator!=null)animator.cancel();animator=ValueAnimator.ofFloat(fraction,value?1:0);animator.setDuration(200);animator.setInterpolator(new DecelerateInterpolator());animator.addUpdateListener(animation->{fraction=(float)animation.getAnimatedValue();for(Header h:headers){ViewGroup.LayoutParams params=h.view.getLayoutParams();params.height=fraction==0?h.originalHeight:Math.max(0,Math.round(h.height*(1-fraction)));h.view.setLayoutParams(params);h.view.setAlpha(1-fraction);h.view.setImportantForAccessibility(fraction==1?View.IMPORTANT_FOR_ACCESSIBILITY_NO_HIDE_DESCENDANTS:View.IMPORTANT_FOR_ACCESSIBILITY_AUTO);}top.position();});animator.start();}
  public void onViewAttachedToWindow(View v){}public void onViewDetachedFromWindow(View v){closed=true;top.close();if(animator!=null)animator.cancel();if(content instanceof RecyclerView&&listener!=null)((RecyclerView)content).removeOnScrollListener(listener);else content.setOnScrollChangeListener(null);content.removeOnAttachStateChangeListener(this);active.remove(content);}
 }
}
